#ifndef SFX_DATA_H
#define SFX_DATA_H

#include <stdint.h>

/* One POKEY register pair as written by the game engine per 80 ms step. */
typedef struct {
    uint8_t audc; /* bits 7-5 distortion, 3-0 volume */
    uint8_t audf; /* 64 kHz (or 1.79 MHz if bit4) clock divider minus 1 */
} SfxStep;

#define SFX_NOTE_COUNT 15
#define SFX_STEPS 16

/* Patterns in ENGINE PLAYBACK order (generated by tools/export_sfx.js
 * from the live RAM table at $B896). */
extern const SfxStep sfx_notes[SFX_NOTE_COUNT][SFX_STEPS];

#endif
